def transform(grid):
    h = len(grid); w = len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    def build(keyfn):
        m = {}
        for r, c, v in cells:
            k = keyfn(r, c)
            if k in m and m[k] != v:
                return None
            m[k] = v
        return m

    best = None
    for keyfn in (lambda r, c: r - c, lambda r, c: r + c):
        m = build(keyfn)
        if m is None:
            continue
        for p in range(1, 31):
            res = {}
            ok = True
            for k, v in m.items():
                rk = k % p
                if rk in res and res[rk] != v:
                    ok = False
                    break
                res[rk] = v
            if ok:
                cand = (p, keyfn, res)
                if best is None or cand[0] < best[0]:
                    best = cand
                break

    if best is None:
        return [row[:] for row in grid]
    p, keyfn, res = best
    return [[res.get(keyfn(r, c) % p, 0) for c in range(w)] for r in range(h)]
